package app.veyra;
import android.content.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.ActivityController;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class TrailerAndQueueUiTest {
 private Button button(View v,String text){if(v instanceof Button&&((Button)v).getText().toString().equals(text))return (Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button found=button(((ViewGroup)v).getChildAt(i),text);if(found!=null)return found;}return null;}
 @Test public void trailersRequireAnExplicitSafeHttpsField()throws Exception{assertEquals("",TrailerSource.url(new JSONObject().put("vod_play_url","https://example.invalid/movie.mp4")));assertEquals("",TrailerSource.url(new JSONObject().put("trailer_url","http://example.invalid/trailer.mp4")));assertEquals("",TrailerSource.url(new JSONObject().put("trailer_url","https://user:password@example.invalid/trailer.mp4")));assertEquals("https://example.invalid/trailer.mp4",TrailerSource.url(new JSONObject().put("trailer_url","https://example.invalid/trailer.mp4")));}
 @Test public void resumeButtonQueuesTheSameTransferAndStartsTheWorker()throws Exception{Context context=RuntimeEnvironment.getApplication();String json="{\"schemaVersion\":1,\"contentId\":\"direct:test\",\"title\":\"Queued film\",\"sources\":[{\"id\":\"original\",\"label\":\"Original\",\"url\":\"https://example.invalid/movie.mp4\",\"mimeType\":\"video/mp4\"}]}";String id=DownloadQueue.add(context,json,"");DownloadQueue.state(context,id,"paused","Paused");Intent intent=new Intent(context,DownloadsActivity.class).putExtra("showTransfers",true);try(ActivityController<DownloadsActivity> controller=Robolectric.buildActivity(DownloadsActivity.class,intent).setup()){java.lang.reflect.Method render=DownloadsActivity.class.getDeclaredMethod("render");render.setAccessible(true);render.invoke(controller.get());View root=controller.get().getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY));root.layout(0,0,1080,1920);Button resume=button(root,"Resume");assertNotNull(resume);resume.performClick();assertEquals("queued",OfflineStore.get(context,id).getString("state"));Intent service=Shadows.shadowOf((android.app.Application)context).getNextStartedService();assertNotNull(service);assertEquals(DownloadWorker.class.getName(),service.getComponent().getClassName());assertEquals(1,DownloadQueue.ordered(context).size());}}
}
